import reactor.core.publisher.Mono;
import java.time.Duration;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import static java.util.concurrent.TimeUnit.MILLISECONDS;

class Issue478_Good1 {
    private final AtomicBoolean lock = new AtomicBoolean(false);

    private Mono<Void> waitForLock(int attempt) {
        return Mono.defer(() -> {
            if(attempt >= 20) {
                return Mono.error(new JWKException("Unable to acquire JWK refresh lock"));
            } else if (lock.compareAndSet(false, true)) {
                return Mono.empty();
            } else {
                return Mono.delay(Duration.ofMillis(50))
                        .then(waitForLock(attempt+1));
            }
        });
    }
}

class Issue478_Good2 {
    private static final int MAX_ATTEMPTS = 10;

    private void foo(int attemptsLeft) {
        if (bar() && attemptsLeft > 0) {
            foo(--attemptsLeft);
        }
    }
    private boolean bar() {
        return true;
    }
}

